Here is the commit message:
perf/amd/ibs: Avoid calling perf_allow_kernel() from the IBS
 NMI handler

Calling perf_allow_kernel() from the NMI context is unsafe and could be
fatal. Capture the permission at event-initialization time by storing it
in event->hw.flags, and have the NMI handler rely on that cached flag
instead of making the call directly.

Fixes: 50a53b60e141d ("perf/amd/ibs: Prevent leaking sensitive data to userspace")
Reported-by: Sadasivan Shaiju <sadasivan.shaiju2@amd.com>
Signed-off-by: Ravi Bangoria <ravi.bangoria@amd.com>
Signed-off-by: Peter Zijlstra (Intel) <peterz@infradead.org>
Acked-by: Namhyung Kim <namhyung@kernel.org>
Link: https://patch.msgid.link/20260216042216.1440-5-ravi.bangoria@amd.com

Here is the root cause:
Calling perf_allow_kernel() from the IBS NMI handler (NMI context) is unsafe and could be fatal; the permission check should be performed at event-initialization time and cached.

Here is the patch:

 static int perf_ibs_init(struct perf_event *event)
 {
 	struct hw_perf_event *hwc = &event->hw;
 	struct perf_ibs *perf_ibs;
 	u64 config;
 	int ret;

 	perf_ibs = get_ibs_pmu(event->attr.type);
 	if (!perf_ibs)
 		return -ENOENT;

 	config = event->attr.config;

 	if (event->pmu != &perf_ibs->pmu)
 		return -ENOENT;

 	if (config & ~perf_ibs->config_mask)
 		return -EINVAL;

 	if (has_branch_stack(event))
 		return -EOPNOTSUPP;

 	/* handle exclude_{user,kernel} in the IRQ handler */
 	if (event->attr.exclude_host || event->attr.exclude_guest ||
 	    event->attr.exclude_idle)
 		return -EINVAL;

 	if (!(event->attr.config2 & IBS_SW_FILTER_MASK) &&
 	    (event->attr.exclude_kernel || event->attr.exclude_user ||
 	     event->attr.exclude_hv))
 		return -EINVAL;

 	ret = validate_group(event);
 	if (ret)
 		return ret;

+	if (perf_allow_kernel())
+		hwc->flags |= PERF_X86_EVENT_UNPRIVILEGED;
+
 	if (hwc->sample_period) {
 		if (config & perf_ibs->cnt_mask)
 			/* raw max_cnt may not be set */
 			return -EINVAL;

 		if (event->attr.freq) {
 			hwc->sample_period = perf_ibs->min_period;
 		} else {
 			/* Silently mask off lower nibble. IBS hw mandates it. */
 			hwc->sample_period &= ~0x0FULL;
 			if (hwc->sample_period < perf_ibs->min_period)
 				return -EINVAL;
 		}
 	} else {
 		u64 period = 0;

 		if (event->attr.freq)
 			return -EINVAL;

 		if (perf_ibs == &perf_ibs_op) {
 			period = (config & IBS_OP_MAX_CNT) << 4;
 			if (ibs_caps & IBS_CAPS_OPCNTEXT)
 				period |= config & IBS_OP_MAX_CNT_EXT_MASK;
 		} else {
 			period = (config & IBS_FETCH_MAX_CNT) << 4;
 		}

 		config &= ~perf_ibs->cnt_mask;
 		event->attr.sample_period = period;
 		hwc->sample_period = period;

 		if (hwc->sample_period < perf_ibs->min_period)
 			return -EINVAL;
 	}

 	if (perf_ibs_ldlat_event(perf_ibs, event)) {
 		u64 ldlat = event->attr.config1 & 0xFFF;

 		if (ldlat < 128 || ldlat > 2048)
 			return -EINVAL;
 		ldlat >>= 7;

 		config |= (ldlat - 1) << 59;

 		config |= IBS_OP_LDLAT_EN;
 		if (cpu_feature_enabled(X86_FEATURE_ZEN5))
 			config |= IBS_OP_L3MISSONLY;
 	}

 	/*
 	 * If we modify hwc->sample_period, we also need to update
 	 * hwc->last_period and hwc->period_left.
 	 */
 	hwc->last_period = hwc->sample_period;
 	local64_set(&hwc->period_left, hwc->sample_period);

 	hwc->config_base = perf_ibs->msr;
 	hwc->config = config;

 	return 0;
 }


 static int perf_ibs_handle_irq(struct perf_ibs *perf_ibs, struct pt_regs *iregs)
 {
 	struct cpu_perf_ibs *pcpu = this_cpu_ptr(perf_ibs->pcpu);
 	struct perf_event *event = pcpu->event;
 	struct hw_perf_event *hwc;
 	struct perf_sample_data data;
 	struct perf_raw_record raw;
 	struct pt_regs regs;
 	struct perf_ibs_data ibs_data;
 	int offset, size, check_rip, offset_max, throttle = 0;
 	unsigned int msr;
 	u64 *buf, *config, period, new_config = 0;
 	int br_target_idx = -1;

 	if (!test_bit(IBS_STARTED, pcpu->state)) {
 fail:
 		/*
 		 * Catch spurious interrupts after stopping IBS: After
 		 * disabling IBS there could be still incoming NMIs
 		 * with samples that even have the valid bit cleared.
 		 * Mark all this NMIs as handled.
 		 */
 		if (test_and_clear_bit(IBS_STOPPED, pcpu->state))
 			return 1;

 		return 0;
 	}

 	if (WARN_ON_ONCE(!event))
 		goto fail;

 	hwc = &event->hw;
 	msr = hwc->config_base;
 	buf = ibs_data.regs;
 	rdmsrq(msr, *buf);
 	if (!(*buf++ & perf_ibs->valid_mask))
 		goto fail;

 	config = &ibs_data.regs[0];
 	perf_ibs_event_update(perf_ibs, event, config);
 	perf_sample_data_init(&data, 0, hwc->last_period);
 	if (!perf_ibs_set_period(perf_ibs, hwc, &period))
 		goto out;	/* no sw counter overflow */

 	ibs_data.caps = ibs_caps;
 	size = 1;
 	offset = 1;
 	check_rip = (perf_ibs == &perf_ibs_op && (ibs_caps & IBS_CAPS_RIPINVALIDCHK));

 	offset_max = perf_ibs_get_offset_max(perf_ibs, event, check_rip);

 	do {
 		rdmsrq(msr + offset, *buf++);
 		size++;
 		offset = find_next_bit(perf_ibs->offset_mask,
 				       perf_ibs->offset_max,
 				       offset + 1);
 	} while (offset < offset_max);

 	if (perf_ibs_ldlat_event(perf_ibs, event)) {
 		union ibs_op_data3 op_data3;

 		op_data3.val = ibs_data.regs[ibs_op_msr_idx(MSR_AMD64_IBSOPDATA3)];
 		/*
 		 * Opening event is errored out if load latency threshold is
 		 * outside of [128, 2048] range. Since the event has reached
 		 * interrupt handler, we can safely assume the threshold is
 		 * within [128, 2048] range.
 		 */
 		if (!op_data3.ld_op || !op_data3.dc_miss ||
 		    op_data3.dc_miss_lat <= (event->attr.config1 & 0xFFF)) {
 			throttle = perf_event_account_interrupt(event);
 			goto out;
 		}
 	}

 	/*
 	 * Read IbsBrTarget, IbsOpData4, and IbsExtdCtl separately
 	 * depending on their availability.
 	 * Can't add to offset_max as they are staggered
 	 */
 	if (event->attr.sample_type & PERF_SAMPLE_RAW) {
 		if (perf_ibs == &perf_ibs_op) {
 			if (ibs_caps & IBS_CAPS_BRNTRGT) {
 				rdmsrq(MSR_AMD64_IBSBRTARGET, *buf++);
 				br_target_idx = size;
 				size++;
 			}
 			if (ibs_caps & IBS_CAPS_OPDATA4) {
 				rdmsrq(MSR_AMD64_IBSOPDATA4, *buf++);
 				size++;
 			}
 		}
 		if (perf_ibs == &perf_ibs_fetch && (ibs_caps & IBS_CAPS_FETCHCTLEXTD)) {
 			rdmsrq(MSR_AMD64_ICIBSEXTDCTL, *buf++);
 			size++;
 		}
 	}
 	ibs_data.size = sizeof(u64) * size;

 	regs = *iregs;
 	if (check_rip && (ibs_data.regs[2] & IBS_RIP_INVALID)) {
 		regs.flags &= ~PERF_EFLAGS_EXACT;
 	} else {
 		/* Workaround for erratum #1197 */
 		if (perf_ibs->fetch_ignore_if_zero_rip && !(ibs_data.regs[1])) {
 			throttle = perf_event_account_interrupt(event);
 			goto out;
 		}

 		set_linear_ip(&regs, ibs_data.regs[1]);
 		regs.flags |= PERF_EFLAGS_EXACT;
 	}

 	if ((event->attr.config2 & IBS_SW_FILTER_MASK) &&
 	    perf_ibs_swfilt_discard(perf_ibs, event, &regs, &ibs_data, br_target_idx)) {
 		throttle = perf_event_account_interrupt(event);
 		goto out;
 	}
 	/*
 	 * Prevent leaking physical addresses to unprivileged users. Skip
 	 * PERF_SAMPLE_PHYS_ADDR check since generic code prevents it for
 	 * unprivileged users.
 	 */
 	if ((event->attr.sample_type & PERF_SAMPLE_RAW) &&
-	    perf_allow_kernel()) {
+	    (hwc->flags & PERF_X86_EVENT_UNPRIVILEGED)) {
 		perf_ibs_phyaddr_clear(perf_ibs, &ibs_data);
 	}

 	if (event->attr.sample_type & PERF_SAMPLE_RAW) {
 		raw = (struct perf_raw_record){
 			.frag = {
 				.size = sizeof(u32) + ibs_data.size,
 				.data = ibs_data.data,
 			},
 		};
 		perf_sample_save_raw_data(&data, event, &raw);
 	}

 	if (perf_ibs == &perf_ibs_op)
 		perf_ibs_parse_ld_st_data(event->attr.sample_type, &ibs_data, &data);

 	/*
 	 * rip recorded by IbsOpRip will not be consistent with rsp and rbp
 	 * recorded as part of interrupt regs. Thus we need to use rip from
 	 * interrupt regs while unwinding call stack.
 	 */
 	perf_sample_save_callchain(&data, event, iregs);

 	throttle = perf_event_overflow(event, &data, &regs);

 	if (event->attr.freq && hwc->sample_period < perf_ibs->min_period)
 		hwc->sample_period = perf_ibs->min_period;

 out:
 	if (!throttle) {
 		if (perf_ibs == &perf_ibs_op) {
 			if (ibs_caps & IBS_CAPS_OPCNTEXT) {
 				new_config = period & IBS_OP_MAX_CNT_EXT_MASK;
 				period &= ~IBS_OP_MAX_CNT_EXT_MASK;
 			}
 			if ((ibs_caps & IBS_CAPS_RDWROPCNT) && (*config & IBS_OP_CNT_CTL))
 				new_config |= *config & IBS_OP_CUR_CNT_RAND;
 		}
 		new_config |= period >> 4;

 		perf_ibs_enable_event(perf_ibs, hwc, new_config);
 	}

 	perf_event_update_userpage(event);

 	return 1;
 }



